import { describe, expect, it } from 'vitest';

import { EDGE_ROUTES } from './edge.routes';

/**
 * Smoke spec for @neuroassist/edge.
 *
 * Generated by fe-architect-promote. Guards the module contract the shell relies on:
 * the route table exists, every route declares a path, and each one lazily loads a component.
 */
describe('@neuroassist/edge route contract', () => {
  it('exposes at least one route', () => {
    expect(Array.isArray(EDGE_ROUTES)).toBe(true);
    expect(EDGE_ROUTES.length).toBeGreaterThan(0);
  });

  it('every route declares a path', () => {
    for (const route of EDGE_ROUTES) {
      expect(typeof route.path).toBe('string');
    }
  });

  it('every route lazily loads a component or redirects', () => {
    for (const route of EDGE_ROUTES) {
      const lazy =
        typeof route.loadComponent === 'function' ||
        typeof route.loadChildren === 'function' ||
        typeof route.redirectTo === 'string';
      expect(lazy).toBe(true);
    }
  });

  it('has no duplicate paths', () => {
    const paths = EDGE_ROUTES.map(r => r.path);
    expect(new Set(paths).size).toBe(paths.length);
  });
});
